[
  {
    "service": "EmployeeService",
    "method": "getEmployees",
    "description": "List employees with optional filters by status/department/location.",
    "params": [
      {
        "name": "orgId",
        "type": "String",
        "required": true
      },
      {
        "name": "query",
        "type": "Object",
        "description": "Filter: { page?, pageSize?, status?, department?, location? }",
        "required": false
      }
    ],
    "returns": "Paginated DTO of bm_employee BaseModels.",
    "group": "business-made"
  },
  {
    "service": "EmployeeService",
    "method": "getEmployee",
    "description": "Fetch a single employee by sk.",
    "params": [
      {
        "name": "orgId",
        "type": "String",
        "required": true
      },
      {
        "name": "id",
        "type": "String",
        "description": "sk of the bm_employee.",
        "required": true
      }
    ],
    "returns": "BaseModel<bm_employee> or null.",
    "group": "business-made"
  },
  {
    "service": "EmployeeService",
    "method": "createEmployee",
    "description": "Create a new employee record. Throws CONFLICT if an employee with the same data.employeeId already exists.",
    "params": [
      {
        "name": "orgId",
        "type": "String",
        "required": true
      },
      {
        "name": "data",
        "type": "Object",
        "description": "Employee payload (e.g., { employeeId?, personalInfo: { firstName, lastName, ... }, contactInfo, employment: { hireDate, status, department, jobTitle, ... } }).",
        "required": true
      },
      {
        "name": "author",
        "type": "String",
        "description": "Audit-trail label; defaults to \"system\".",
        "required": false
      }
    ],
    "returns": "The persisted bm_employee BaseModel.",
    "group": "business-made"
  },
  {
    "service": "EmployeeService",
    "method": "updateEmployee",
    "description": "Update an employee in full.",
    "params": [
      {
        "name": "orgId",
        "type": "String",
        "required": true
      },
      {
        "name": "data",
        "type": "Object",
        "description": "Full bm_employee BaseModel including sk and updated data.",
        "required": true
      }
    ],
    "returns": "The updated bm_employee BaseModel.",
    "group": "business-made"
  },
  {
    "service": "EmployeeService",
    "method": "deleteEmployee",
    "description": "Soft-delete an employee.",
    "params": [
      {
        "name": "orgId",
        "type": "String",
        "required": true
      },
      {
        "name": "id",
        "type": "String",
        "description": "sk of the bm_employee.",
        "required": true
      },
      {
        "name": "deletedBy",
        "type": "String",
        "description": "Audit-trail label; defaults to \"system\".",
        "required": false
      }
    ],
    "returns": "Delete result from the repository.",
    "group": "business-made"
  },
  {
    "service": "EmployeeService",
    "method": "getEmployeeByEmployeeId",
    "description": "Look up an employee by their human-readable employeeId code.",
    "params": [
      {
        "name": "orgId",
        "type": "String",
        "required": true
      },
      {
        "name": "employeeId",
        "type": "String",
        "description": "data.employeeId value (e.g., \"EMP-1001\").",
        "required": true
      }
    ],
    "returns": "The matching bm_employee BaseModel or null.",
    "group": "business-made"
  },
  {
    "service": "EmployeeService",
    "method": "getEmployeesByDepartment",
    "description": "List employees in a given department.",
    "params": [
      {
        "name": "orgId",
        "type": "String",
        "required": true
      },
      {
        "name": "department",
        "type": "String",
        "description": "Department name (matches data.employment.department).",
        "required": true
      },
      {
        "name": "query",
        "type": "Object",
        "required": false
      }
    ],
    "returns": "Paginated DTO of matching bm_employee BaseModels.",
    "group": "business-made"
  },
  {
    "service": "EmployeeService",
    "method": "getEmployeesByLocation",
    "description": "List employees at a given location.",
    "params": [
      {
        "name": "orgId",
        "type": "String",
        "required": true
      },
      {
        "name": "location",
        "type": "String",
        "description": "Location identifier or name (matches data.employment.location).",
        "required": true
      },
      {
        "name": "query",
        "type": "Object",
        "required": false
      }
    ],
    "returns": "Paginated DTO of matching bm_employee BaseModels.",
    "group": "business-made"
  },
  {
    "service": "EmployeeService",
    "method": "getActiveEmployees",
    "description": "List all active employees (data.employment.status = active).",
    "params": [
      {
        "name": "orgId",
        "type": "String",
        "required": true
      },
      {
        "name": "query",
        "type": "Object",
        "required": false
      }
    ],
    "returns": "Paginated DTO of active bm_employee BaseModels.",
    "group": "business-made"
  },
  {
    "service": "EmployeeService",
    "method": "getEmployeesBySupervisor",
    "description": "List direct reports of a supervisor.",
    "params": [
      {
        "name": "orgId",
        "type": "String",
        "required": true
      },
      {
        "name": "supervisorId",
        "type": "String",
        "description": "sk of the supervising bm_employee (matches data.employment.supervisor).",
        "required": true
      },
      {
        "name": "query",
        "type": "Object",
        "required": false
      }
    ],
    "returns": "Paginated DTO of matching bm_employee BaseModels.",
    "group": "business-made"
  },
  {
    "service": "EmployeeService",
    "method": "updateEmployeeStatus",
    "description": "Set an employee's employment status. Stamps statusChangedAt + reason; sets endDate if status is \"terminated\".",
    "params": [
      {
        "name": "orgId",
        "type": "String",
        "required": true
      },
      {
        "name": "id",
        "type": "String",
        "description": "sk of the bm_employee.",
        "required": true
      },
      {
        "name": "status",
        "type": "String",
        "description": "New status string (e.g., \"active\", \"on_leave\", \"terminated\", \"suspended\").",
        "required": true
      },
      {
        "name": "reason",
        "type": "String",
        "description": "Optional reason recorded on data.employment.statusChangeReason.",
        "required": true
      }
    ],
    "returns": "The updated bm_employee BaseModel.",
    "group": "business-made"
  },
  {
    "service": "EmployeeService",
    "method": "terminateEmployee",
    "description": "Terminate an employee — sets status terminated, stamps endDate, records termination metadata block.",
    "params": [
      {
        "name": "orgId",
        "type": "String",
        "required": true
      },
      {
        "name": "id",
        "type": "String",
        "description": "sk of the bm_employee.",
        "required": true
      },
      {
        "name": "terminationData",
        "type": "Object",
        "description": "{ reason, effectiveDate? (ISO YYYY-MM-DD, defaults today), terminationType: voluntary|involuntary|retirement|other, eligibleForRehire?, notes? }",
        "required": true
      }
    ],
    "returns": "The updated bm_employee BaseModel.",
    "group": "business-made"
  },
  {
    "service": "EmployeeService",
    "method": "requestTimeOff",
    "description": "Submit a time-off request — appends to employee.timeOffRequests with status pending.",
    "params": [
      {
        "name": "orgId",
        "type": "String",
        "required": true
      },
      {
        "name": "employeeId",
        "type": "String",
        "description": "Employee ID — the badge number, e.g. EMP-1043.",
        "required": true
      },
      {
        "name": "request",
        "type": "Object",
        "description": "{ type: vacation|sick|personal|unpaid|bereavement|jury_duty|other, startDate (ISO YYYY-MM-DD), endDate (ISO YYYY-MM-DD), hours, reason? }",
        "required": true
      }
    ],
    "returns": "The newly-created time-off request object (with generated id and status=\"pending\").",
    "group": "business-made"
  },
  {
    "service": "EmployeeService",
    "method": "approveTimeOff",
    "description": "Approve a time-off request — sets status approved and deducts the hours from the employee's PTO balance (vacation/sick/personal).",
    "params": [
      {
        "name": "orgId",
        "type": "String",
        "required": true
      },
      {
        "name": "employeeId",
        "type": "String",
        "description": "Employee ID — the badge number, e.g. EMP-1043.",
        "required": true
      },
      {
        "name": "requestId",
        "type": "String",
        "description": "id of the time-off request within data.timeOffRequests.",
        "required": true
      },
      {
        "name": "approvedBy",
        "type": "String",
        "description": "Approver identifier.",
        "required": true
      }
    ],
    "returns": "The updated bm_employee BaseModel.",
    "group": "business-made"
  },
  {
    "service": "EmployeeService",
    "method": "rejectTimeOff",
    "description": "Reject a time-off request — sets status rejected, stamps rejecter and reason.",
    "params": [
      {
        "name": "orgId",
        "type": "String",
        "required": true
      },
      {
        "name": "employeeId",
        "type": "String",
        "description": "Employee ID — the badge number, e.g. EMP-1043.",
        "required": true
      },
      {
        "name": "requestId",
        "type": "String",
        "description": "id of the time-off request within data.timeOffRequests.",
        "required": true
      },
      {
        "name": "rejectedBy",
        "type": "String",
        "description": "Rejecter identifier.",
        "required": true
      },
      {
        "name": "reason",
        "type": "String",
        "description": "Free-text rejection reason.",
        "required": true
      }
    ],
    "returns": "The updated bm_employee BaseModel.",
    "group": "business-made"
  },
  {
    "service": "EmployeeService",
    "method": "getTimeOffRequests",
    "description": "List time-off requests on an employee, optionally filtered by status.",
    "params": [
      {
        "name": "orgId",
        "type": "String",
        "required": true
      },
      {
        "name": "employeeId",
        "type": "String",
        "description": "Employee ID — the badge number, e.g. EMP-1043.",
        "required": true
      },
      {
        "name": "status",
        "type": "String",
        "description": "Optional status filter (pending|approved|rejected).",
        "required": true
      }
    ],
    "returns": "Array of time-off request objects from data.timeOffRequests.",
    "group": "business-made"
  },
  {
    "service": "EmployeeService",
    "method": "addPerformanceReview",
    "description": "Append a performance review record to an employee.",
    "params": [
      {
        "name": "orgId",
        "type": "String",
        "required": true
      },
      {
        "name": "employeeId",
        "type": "String",
        "description": "Employee ID — the badge number, e.g. EMP-1043.",
        "required": true
      },
      {
        "name": "review",
        "type": "Object",
        "description": "{ reviewType: annual|quarterly|probation|promotion|improvement, reviewDate (ISO), reviewerId, reviewerName, rating (number), strengths?, areasForImprovement?, goals?, comments? }",
        "required": true
      }
    ],
    "returns": "The newly-appended performance-review object (with generated id).",
    "group": "business-made"
  },
  {
    "service": "EmployeeService",
    "method": "getPerformanceReviews",
    "description": "Read all performance reviews on an employee record.",
    "params": [
      {
        "name": "orgId",
        "type": "String",
        "required": true
      },
      {
        "name": "employeeId",
        "type": "String",
        "description": "Employee ID — the badge number, e.g. EMP-1043.",
        "required": true
      }
    ],
    "returns": "Array of performance-review objects from data.performanceReviews.",
    "group": "business-made"
  },
  {
    "service": "EmployeeService",
    "method": "addTraining",
    "description": "Assign a training record to an employee — appends to data.training with status assigned.",
    "params": [
      {
        "name": "orgId",
        "type": "String",
        "required": true
      },
      {
        "name": "employeeId",
        "type": "String",
        "description": "Employee ID — the badge number, e.g. EMP-1043.",
        "required": true
      },
      {
        "name": "training",
        "type": "Object",
        "description": "{ trainingName, trainingType: safety|technical|compliance|leadership|onboarding|other, completionDate?, expirationDate?, instructor?, certificateNumber?, score?, status: assigned|in_progress|completed|expired, notes? }",
        "required": true
      }
    ],
    "returns": "The updated bm_employee BaseModel.",
    "group": "business-made"
  },
  {
    "service": "EmployeeService",
    "method": "completeTraining",
    "description": "Mark an assigned training as completed — sets status completed and stamps completion data.",
    "params": [
      {
        "name": "orgId",
        "type": "String",
        "required": true
      },
      {
        "name": "employeeId",
        "type": "String",
        "description": "Employee ID — the badge number, e.g. EMP-1043.",
        "required": true
      },
      {
        "name": "trainingId",
        "type": "String",
        "description": "id of the training record within data.training.",
        "required": true
      },
      {
        "name": "completionData",
        "type": "Object",
        "description": "{ completionDate (ISO), score?, certificateNumber?, expirationDate? }",
        "required": true
      }
    ],
    "returns": "The updated bm_employee BaseModel.",
    "group": "business-made"
  },
  {
    "service": "EmployeeService",
    "method": "getExpiredTraining",
    "description": "Sweep all active employees and return training records whose expirationDate is past today.",
    "params": [
      {
        "name": "orgId",
        "type": "String",
        "required": true
      }
    ],
    "returns": "Array of { employeeId, employeeName, training } for every expired training entry.",
    "group": "business-made"
  },
  {
    "service": "EmployeeService",
    "method": "addSkill",
    "description": "Add or replace a skill on an employee. If a skill with the same skillName exists, it's merged-updated.",
    "params": [
      {
        "name": "orgId",
        "type": "String",
        "required": true
      },
      {
        "name": "employeeId",
        "type": "String",
        "description": "Employee ID — the badge number, e.g. EMP-1043.",
        "required": true
      },
      {
        "name": "skill",
        "type": "Object",
        "description": "{ skillName, proficiencyLevel: beginner|intermediate|advanced|expert, certificationRequired?, certificationDate?, expirationDate? }",
        "required": true
      }
    ],
    "returns": "The updated bm_employee BaseModel.",
    "group": "business-made"
  },
  {
    "service": "EmployeeService",
    "method": "getEmployeesBySkill",
    "description": "Find active employees who have a given skill at or above a minimum proficiency.",
    "params": [
      {
        "name": "orgId",
        "type": "String",
        "required": true
      },
      {
        "name": "skillName",
        "type": "String",
        "description": "Skill name to match.",
        "required": true
      },
      {
        "name": "minProficiency",
        "type": "String",
        "description": "Optional minimum: beginner|intermediate|advanced|expert.",
        "required": true
      }
    ],
    "returns": "Array of bm_employee BaseModels matching the criteria.",
    "group": "business-made"
  },
  {
    "service": "EmployeeService",
    "method": "startOnboarding",
    "description": "Initialize an onboarding checklist on an employee — sets data.onboarding with status in_progress and the provided task list.",
    "params": [
      {
        "name": "orgId",
        "type": "String",
        "required": true
      },
      {
        "name": "employeeId",
        "type": "String",
        "description": "Employee ID — the badge number, e.g. EMP-1043.",
        "required": true
      },
      {
        "name": "tasks",
        "type": "Array",
        "description": "Array of { taskName, dueDate? (ISO), assignedTo? } objects to seed the checklist with.",
        "required": true
      }
    ],
    "returns": "The updated bm_employee BaseModel.",
    "group": "business-made"
  },
  {
    "service": "EmployeeService",
    "method": "completeOnboardingTask",
    "description": "Mark one onboarding task complete. Auto-completes the whole onboarding when all tasks are done.",
    "params": [
      {
        "name": "orgId",
        "type": "String",
        "required": true
      },
      {
        "name": "employeeId",
        "type": "String",
        "description": "Employee ID — the badge number, e.g. EMP-1043.",
        "required": true
      },
      {
        "name": "taskId",
        "type": "String",
        "description": "id of the task within data.onboarding.tasks.",
        "required": true
      },
      {
        "name": "completedBy",
        "type": "String",
        "description": "Identifier of who completed the task.",
        "required": true
      }
    ],
    "returns": "The updated bm_employee BaseModel.",
    "group": "business-made"
  },
  {
    "service": "EmployeeService",
    "method": "getHeadcount",
    "description": "Headcount snapshot — counts active employees, broken down by department, location, and employment type.",
    "params": [
      {
        "name": "orgId",
        "type": "String",
        "required": true
      }
    ],
    "returns": "{ total, byDepartment, byLocation, byEmploymentType }.",
    "group": "business-made"
  },
  {
    "service": "EmployeeService",
    "method": "getUpcomingAnniversaries",
    "description": "List active employees whose work anniversary falls within the next `daysAhead` days, sorted by daysUntil ascending.",
    "params": [
      {
        "name": "orgId",
        "type": "String",
        "required": true
      },
      {
        "name": "daysAhead",
        "type": "Number",
        "description": "Lookahead window in days; defaults to 30.",
        "required": false
      }
    ],
    "returns": "Array of { employeeId, employeeName, anniversaryDate, yearsOfService, daysUntil }.",
    "group": "business-made"
  },
  {
    "service": "EmployeeService",
    "method": "getUpcomingBirthdays",
    "description": "List active employees whose birthday falls within the next `daysAhead` days, sorted by daysUntil ascending.",
    "params": [
      {
        "name": "orgId",
        "type": "String",
        "required": true
      },
      {
        "name": "daysAhead",
        "type": "Number",
        "description": "Lookahead window in days; defaults to 30.",
        "required": false
      }
    ],
    "returns": "Array of { employeeId, employeeName, birthdayDate, daysUntil }.",
    "group": "business-made"
  }
]
